                            bn = emon.Port.cellsAt(bw, ((end - 1) * 4) + 2) + 1;
                            lines = msContentLines(keys, codepoints, a, an);
                            other = msContentLines(keys, codepoints, b, bn);
                            lines = msMin(lines, other);
